import json,hashlib,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.settings import PACK as P,RUNTIME as RUN
def main():
 roi=json.loads((ROOT/'config/roi.json').read_text(encoding='utf-8'))
 records=[]
 def add(id,url,instrument,product,format,path,resolution,status,notes,**extra):
  file=P/path if path else None
  item=dict(id=id,url_tested=url,retrieved_utc='2026-11-15; original pack collection 2026-11-14',agency_mission='NASA/USGS; MRO or Mars2020 as specified',instrument=instrument,product_id=product,format=format,
   licence_attribution='Public scientific source; producer attribution retained; see docs/attributions.md',bytes=file.stat().st_size if file else None,
   extension=file.suffix if file else None,sha256=hashlib.sha256(file.read_bytes()).hexdigest() if file else None,
   nominal_resolution=resolution,crs=roi['crs_wkt'],latitude_type='Planetocentric',longitude_domain='0–360°, positive east',
   horizontal_units='metres in local Mars projection; degrees in source WMTS',vertical_units='not applicable unless DEM',
   uncertainty='Absolute positional accuracy not independently quantified',acquisition='individual acquisition times unknown; mosaics are historical',
   bbox=roi['extent_lonlat_mars'],nodata='see raster-audit.json / source metadata',integration=status,notes=notes)
  item.update(extra);records.append(item)
 catalog=json.loads((P/'imagery/mars_trek/catalogue_jezero.json').read_text(encoding='utf-8'))
 for name,layer,nom in [('HiRISE','JEZ_hirise_soc_006_orthoMosaic_25cm_Eqc_latTs0_lon0_first_dd','0.25 m nominal mosaic; delivered cache ~1.2 m; display 2 m'),('CTX','JEZ_ctx_B_soc_008_orthoMosaic_6m_Eqc_latTs0_lon0','6 m nominal mosaic; delivered cache ~10 m; display resampled 2 m')]:
  info=next(x for x in catalog if x.get('productLabel')==layer)
  add(name,f'https://trek.nasa.gov/tiles/Mars/EQ/{layer}/1.0.0/WMTSCapabilities.xml',name,layer,'GeoTIFF / WMTS PNG',f'imagery/mars_trek/{name}_extrait_MARS.tif',nom,'VERIFIED_USED','Offline source reprojected to PLACES; registration residual unknown',source_bbox=info['bbox'],catalog_created=info.get('data_created_date'),source_crs=info['projection'])
 add('PLACES DEM','https://pds-geosciences.wustl.edu/m2020/urn-nasa-pds-mars2020_rover_places/data_maps/m20_orbital_dem.xml','MRO orbital HiRISE/CTX, harmonized PLACES','urn:nasa:pds:mars2020_rover_places:data_maps:m20_orbital_dem::16.0','Float32 GeoTIFF clip','terrain/relief_delta.tif','native 1 m; conservative routing grid 5 m','VERIFIED_USED','No resampling of native elevations in supplied clip; source crop provenance supplied by pack',vertical_units='metres; absolute datum/accuracy not independently established',nodata='No invalid pixels in ROI; source nodata recorded in raster-audit.json',acquisition='PDS label observation window 2021-02-18 to 2026-06-21 is archive coverage, NOT orbital acquisition date')
 add('SIM3464','https://pubs.usgs.gov/sim/3464/','Geologic interpretation from orbital observations','USGS SIM3464 Sun & Stack 2020; GeoUnits_v1','Original archive/GDB and converted GPKG','geology/usgs_original_MARS.gpkg','1:75,000','VERIFIED_USED','1304 authoritative polygons; transformed/clipped to five ROI polygons; unregistered',uncertainty='100–200 m relative Mars2020 context; not rock-scale identification',acquisition='Publication 2020; compilation from multiple historical acquisitions',source_crs='Mars TM, central meridian 77.5°E, R3396190 m',licence_attribution='USGS Sun & Stack 2020 DOI10.3133/sim3464')
 add('CTX DEM catalog','https://astrogeology.usgs.gov/search/map/mars_2020_science_investigation_ctx_dem_mosaic','CTX MRO','M20_JezeroCrater_CTXDEM_20m.tif','GeoTIFF',None,'20 m','VERIFIED_NOT_USED','Official download link identified (~87 MB); local routing instead uses PLACES 1 m',bbox='Catalog coverage not imported; do not infer valid cells from title',crs='Not independently inspected for this remote file')
 add('HiRISE DTM candidate','https://www.uahirise.org/dtm/ESP_045994_1985','HiRISE MRO','DTEEC_045994_1985_046060_1985_U01','PDS IMG',None,'1 m nominal','VERIFIED_NOT_USED','Catalog checked, 381 MB DTM not downloaded; not equated to PLACES by identity',bbox='catalog center 18.4N,77.44E; footprint not imported',crs='Not independently inspected for this remote DTM')
 add('Murray DEM','https://murray-lab.caltech.edu/Mars2020/index.html','MRO orbital stereo','Western channel/fan DEM catalog','ZIP',None,'1 m per requested catalog; not verified here','UNAVAILABLE','TLS certificate verification failed; no bypass',crs='unknown',bbox='unknown')
 add('CRISM','https://zenodo.org/records/22257754','CRISM MRO; derived map by Valantinas et al.','FRT00005850; supporting HRL000040FF/FRS0002FE75/FRS00031442','Class GeoTIFF, JSON, SHP in core ZIP',None,'18 m class mapping','VERIFIED_NOT_USED','Core ZIP downloaded, published MD5 matched. All three class rasters: ZERO valid pixels in ROI. No local mineral layer.',source_crs='ESRI:104971 Mars sphere geographic; TIFF bounds inspected',source_bbox=[77.219978566,18.170557501,77.436799580,18.701981554],uncertainty='Primary registration ~28 m RMS (independent points) within stated validation area; not transferable to absent ROI pixels',licence_attribution='Valantinas et al. 2026, derived maps CC BY4.0',nodata=0,acquisition='Multiple historical orbital observations; publication 2026, not acquisition date')
 add('Mastcam-Z figures','https://pds-geosciences.wustl.edu/missions/mars2020/Mars%202020%20Initial%20Reports%20Volume%202%20Release%202.pdf','Perseverance Mastcam-Z','Swift Run Figure5; Hazeltop Figure5; Shuyak Figure5','PDF/PNG','sources/pds/Mars2020_Initial_Reports_Vol2_Release2.pdf','Image figures; not georeferenced raster','VERIFIED_USED','Three figures preserved with legends, instrument/sols/sequences in config/site-image-metadata.json',crs='none for individual figure pixels',bbox='Sites A/B/C associated by report; no exact pixel footprint',acquisition='Mastcam-Z sols466/492,513,557/565/582; distinct from sample sols490/509/575',nodata='not applicable')
 add('MEDA','https://pds-geosciences.wustl.edu/missions/mars2020/','Mars2020 MEDA','WE__0029 derived products','CSV/XML','environment/MEDA_sol_0029/WE__0029___________DER_PS__________________P01.CSV','historical time series at rover','VERIFIED_USED','Pressure only: XML confirms pascal; 50,926 valid samples, 729.2–755.4 Pa. Humidity absent; questionable uncertainty unit excluded; TIRS not converted to temperature. Not current ROI weather.',acquisition='sol29; UTC 2021-03-19 through 2021-03-21',bbox='rover measurement location; not a regional map',crs='none for time series')
 add('EVA scenario',None,'none; simulation','mars-grid-2.1-native-edges','JSON/SQLite',None,'5 m conservative graph; every edge and profile checked on native 1 m DEM','SIMULATED','Base, walking law, speed, stops, reserve, visibility and events are demonstration hypotheses. User notes are unverified.',licence_attribution='Independent scenario',acquisition='simulation clock',uncertainty='Not operationally validated')
 (RUN/'datasets.json').write_text(json.dumps(records,indent=2,ensure_ascii=False),encoding='utf-8')
 rows=['# Scientific source audit — 15 November 2026','','The 120 release files were checked against their SHA-256 manifest. Bounded HTTP requests, CORS headers, response codes and checksums are recorded in runtime/network-audit.json and runtime/source-checks/. A 206 response validates a ranged request, not a complete import.','','Full product metadata are exposed in runtime/datasets.json and /api/v1/datasets. Native raster properties are recorded in runtime/raster-audit.json.','','| Product | Integration | Resolution / scale | Verified result |','|---|---|---|---|']
 for d in records:rows.append(f"| {d['id']} | {d['integration']} | {d['nominal_resolution']} | {d['notes']} |")
 rows+=['','## Selected area','','The PLACES DEM rectangle is within the supplied HiRISE/CTX coverage. All 1,560,000 native cells are valid. Five original USGS polygons intersect this area. All three published sample sites are within coverage. Reprojection was checked; fine registration was not independently established. The human base is a simulation assumption.','','## Specific checks','','WMTS capabilities: default style, default028mm matrix set, PNG; HiRISE levels0–17 and CTX0–13. The published double slash in ResourceURL is preserved. Tested tiles returned image/png and Access-Control-Allow-Origin: *. The service uses Mars geographic coordinates, not terrestrial Web Mercator. Nominal source resolution differs from cached image resolution.','','CRISM: the 1.3 MB core archive was downloaded and its published MD5 5d923ebaf76804a184b4a3a1911e5214 matched. The three class maps, nominally18m with NoData0, have zero valid pixels in the selected area despite overlapping rectangular bounds. Evidence: runtime/crism-coverage.json. No replacement mineral map was invented.','','USGS: the local archive is349336873bytes, pamphlet728435bytes and map36406378bytes. Original polygons contain1304 features versus1308 in a web export, so OBJECTID joins are excluded. Unit descriptions are joined by name and interpreted regionally. SIM3464 is unregistered with a possible100–200m offset and is excluded from fine routing.','','Catalogue creation dates and the PLACES label observation window are not individual orbital acquisition dates. Unknowns remain explicit. No real-time data or RGB-derived elevations are claimed.']
 (ROOT/'docs/data-source-audit.md').write_text('\n'.join(rows)+'\n',encoding='utf-8')
if __name__=='__main__':main()
